def cmp_semver(a, b):
    # Ignore build metadata after +
    a = a.split('+')[0]
    b = b.split('+')[0]

    # Split version and pre-release
    if '-' in a:
        core_a, pre_a = a.split('-', 1)
    else:
        core_a = a
        pre_a = None

    if '-' in b:
        core_b, pre_b = b.split('-', 1)
    else:
        core_b = b
        pre_b = None

    # Parse major.minor.patch numerically
    ca = list(map(int, core_a.split('.')))
    cb = list(map(int, core_b.split('.')))

    for x, y in zip(ca, cb):
        if x < y:
            return -1
        if x > y:
            return 1

    # Core versions equal, handle pre-release
    has_pre_a = pre_a is not None
    has_pre_b = pre_b is not None

    if has_pre_a and has_pre_b:
        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')

        for x, y in zip(ids_a, ids_b):
            x_num = x.isdigit()
            y_num = y.isdigit()

            if x_num and y_num:
                xi, yi = int(x), int(y)
                if xi < yi:
                    return -1
                if xi > yi:
                    return 1
            elif x_num and not y_num:
                return -1  # numeric sorts before alphanumeric
            elif not x_num and y_num:
                return 1
            else:
                # both alphanumeric, compare lexicographically (ASCII)
                if x < y:
                    return -1
                if x > y:
                    return 1

        # All compared identifiers equal; shorter list has lower precedence
        if len(ids_a) < len(ids_b):
            return -1
        if len(ids_a) > len(ids_b):
            return 1
        return 0

    elif has_pre_a and not has_pre_b:
        # version with pre-release sorts BEFORE the same version without
        return -1
    elif not has_pre_a and has_pre_b:
        return 1
    else:
        # Neither has pre-release, versions are equal
        return 0
