def parse_range(header, size):
    if not isinstance(header, str):
        return None
    h = header.strip()
    if not h.lower().startswith('bytes='):
        return None

    spec = h[6:].strip()
    if not spec:
        return None

    range_specs = spec.split(',')
    satisfiable = []

    for rs in range_specs:
        rs = rs.strip()
        if not rs:
            continue

        # Suffix format: -<digits>
        if rs.startswith('-'):
            try:
                suffix_len = int(rs[1:].strip())
            except ValueError:
                return None
            if size == 0 or suffix_len <= 0:
                continue
            if suffix_len >= size:
                satisfiable.append((0, size - 1))
            else:
                start = size - suffix_len
                end = size - 1
                if start <= end:
                    satisfiable.append((start, end))

        # Start-to-end format: <digits>- or <digits> (with trailing dash)
        elif rs.endswith('-'):
            try:
                start = int(rs[:-1].strip())
            except ValueError:
                return None
            if start >= size:
                continue
            satisfiable.append((start, size - 1))

        # First-last format: <digits>-<digits>
        elif '-' in rs:
            parts = rs.split('-', 1)
            start_str = parts[0].strip()
            end_str = parts[1].strip()

            try:
                start = int(start_str) if start_str else None
            except ValueError:
                return None
            try:
                end = int(end_str) if end_str else None
            except ValueError:
                return None

            if start is not None and end is not None:
                if start >= size:
                    continue
                if end < start:
                    continue
                if end >= size:
                    end = size - 1
                if start > end:
                    continue
                satisfiable.append((start, end))

            elif start is not None and end is None:
                if start >= size:
                    continue
                satisfiable.append((start, size - 1))

            else:
                return None

        else:
            return None

    if not satisfiable:
        return None
    return satisfiable
