from collections import OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.min_freq = 0
        self.key_val_freq = {}  # key -> (value, freq)
        self.freq_keys = {}  # freq -> OrderedDict of keys (ordered by recency)

    def get(self, key: int) -> int:
        if key not in self.key_val_freq:
            return -1
        val, freq = self.key_val_freq[key]
        self._update(key, val, freq)
        return val

    def put(self, key: int, value: int) -> None:
        if self.cap == 0:
            return
        if key in self.key_val_freq:
            old_val, freq = self.key_val_freq[key]
            self.key_val_freq[key] = (value, freq)
            self._update(key, value, freq)
        else:
            if len(self.key_val_freq) >= self.cap:
                # evict the least frequently used key; break ties by LRU
                k, _ = self.freq_keys[self.min_freq].popitem(last=False)
                del self.key_val_freq[k]
            self.key_val_freq[key] = (value, 1)
            if 1 not in self.freq_keys:
                self.freq_keys[1] = OrderedDict()
            self.freq_keys[1][key] = value
            self.min_freq = 1

    def _update(self, key: int, val: int, freq: int) -> None:
        # remove from current frequency list
        del self.freq_keys[freq][key]
        if not self.freq_keys[freq] and self.min_freq == freq:
            self.min_freq += 1
        # add to new frequency list
        new_freq = freq + 1
        if new_freq not in self.freq_keys:
            self.freq_keys[new_freq] = OrderedDict()
        self.freq_keys[new_freq][key] = val
        self.key_val_freq[key] = (val, new_freq)

