import heapq

def topk(stream, k):
    if k <= 0:
        return []
    heap = []
    counter = 0
    for value, label in stream:
        key = (value, -counter)
        if len(heap) < k:
            heapq.heappush(heap, (key, label))
        else:
            if key > heap[0][0]:
                heapq.heapreplace(heap, (key, label))
        counter += 1
    result = []
    for (val, neg_arr), lbl in heap:
        arrival_idx = -neg_arr
        result.append((val, lbl, arrival_idx))
    result.sort(key=lambda x: (-x[0], x[2]))
    return [(val, lbl) for val, lbl, _ in result]

