from datetime import datetime, timedelta
import calendar


def parse_field(field_str, min_val, max_val):
    terms = field_str.split(',')
    values = set()
    for term in terms:
        term = term.strip()
        if not term:
            raise ValueError(f"Empty term in cron field: {field_str}")
        if '/' in term:
            range_part, step_str = term.split('/', 1)
            try:
                step = int(step_str)
            except Exception:
                raise ValueError(f"Invalid step in field: {term}")
            if step <= 0:
                raise ValueError(f"Step must be positive: {step}")
            if range_part == '*':
                start = min_val
                end = max_val
            elif '-' in range_part:
                a, b = range_part.split('-', 1)
                try:
                    a, b = int(a), int(b)
                except Exception:
                    raise ValueError(f"Invalid range in field: {term}")
                if a < min_val or b > max_val or a > b:
                    raise ValueError(f"Range out of bounds or invalid: {range_part}")
                start, end = a, b
            else:
                raise ValueError(f"Invalid step range syntax: {term}")
            for v in range(start, end + 1, step):
                if v < min_val or v > max_val:
                    raise ValueError(f"Value {v} out of bounds in field")
                values.add(v)
        elif term == '*':
            values.update(range(min_val, max_val + 1))
        elif '-' in term:
            a, b = term.split('-', 1)
            try:
                a, b = int(a), int(b)
            except Exception:
                raise ValueError(f"Invalid range: {term}")
            if a < min_val or b > max_val or a > b:
                raise ValueError(f"Range out of bounds: {range_part}")
            values.update(range(a, b + 1))
        else:
            try:
                val = int(term)
            except Exception:
                raise ValueError(f"Invalid number: {term}")
            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of bounds")
            values.add(val)
    return sorted(values)


def next_fire(expr, after):
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    field_ranges = [
        (0, 59),    # minute
        (0, 23),    # hour
        (1, 31),    # day-of-month
        (1, 12),    # month
        (0, 6)      # day-of-week (0=Sunday)
    ]

    parsed = []
    for i, field in enumerate(fields):
        min_val, max_val = field_ranges[i]
        parsed.append(parse_field(field, min_val, max_val))

    minute_set, hour_set, dom_set, month_set, dow_set = parsed

    FULL_DOM = set(range(1, 32))
    FULL_DOW = set(range(0, 7))
    dom_restricted = set(dom_set) != FULL_DOM
    dow_restricted = set(dow_set) != FULL_DOW

    # Start strictly after `after`, with seconds and microseconds zero
    cand = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    max_iter = 5 * 366 * 24 * 60  # safety cap (~10 years of minutes)
    for _ in range(max_iter):
        if cand.minute not in minute_set or \
           cand.hour not in hour_set or \
           cand.month not in month_set:
            cand += timedelta(minutes=1)
            continue

        last_day = calendar.monthrange(cand.year, cand.month)[1]
        if cand.day > last_day:
            if cand.month == 12:
                cand = datetime(cand.year + 1, 1, 1, 0, 0)
            else:
                cand = datetime(cand.year, cand.month + 1, 1, 0, 0)
            continue

        # Convert Python weekday (Mon=0..Sun=6) to cron dow (Sun=0..Sat=6)
        py_wd = cand.weekday()
        cron_dow = (py_wd + 1) % 7

        day_matches = False
        if dom_restricted and dow_restricted:
            if cand.day in dom_set or cron_dow in dow_set:
                day_matches = True
        elif dom_restricted:
            if cand.day in dom_set:
                day_matches = True
        elif dow_restricted:
            if cron_dow in dow_set:
                day_matches = True
        else:
            day_matches = True

        if not day_matches:
            if cand.month == 12:
                cand = datetime(cand.year + 1, 1, 1, 0, 0)
            else:
                cand = datetime(cand.year, cand.month + 1, 1, 0, 0)
            continue

        return cand

    raise ValueError("No matching time found within search limit")
