class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.sz = [1] * n
        self._comp = n
        self._history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.sz[ra] < self.sz[rb]:
            ra, rb = rb, ra
        # record old state for rollback
        self._history.append((rb, ra, self.sz[ra]))
        self.parent[rb] = ra
        self.sz[ra] += self.sz[rb]
        self._comp -= 1
        return True

    def snapshot(self):
        return len(self._history)

    def rollback(self, token):
        while len(self._history) > token:
            rb, ra, old_sz = self._history.pop()
            self.parent[rb] = rb
            self.sz[ra] = old_sz
            self._comp += 1

    def components(self):
        return self._comp
