def subtract(base, cuts):
    # Remove empty intervals from inputs (where start >= end)
    base = [iv for iv in base if iv[0] < iv[1]]
    cuts = [iv for iv in cuts if iv[0] < iv[1]]

    def merge_intervals(intervals):
        """Merge overlapping or touching half-open intervals."""
        if not intervals:
            return []
        sorted_ints = sorted(intervals, key=lambda x: (x[0], x[1]))
        merged = [list(sorted_ints[0])]
        for start, end in sorted_ints[1:]:
            if start <= merged[-1][1]:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        return merged

    base_merged = merge_intervals(base)
    cuts_merged = merge_intervals(cuts)

    def subtract_one_base(a_start, a_end, cuts):
        """Return surviving sub-intervals of [a_start, a_end) after subtracting sorted disjoint cuts."""
        res = []
        cur_start = a_start
        for b_start, b_end in cuts:
            if b_end <= cur_start:
                continue          # cut entirely before current remaining part
            if b_start >= a_end:
                break             # cut starts after base interval ends
            if b_start > cur_start:
                res.append([cur_start, b_start])
            cur_start = max(cur_start, b_end)
            if cur_start >= a_end:
                break
        if cur_start < a_end:
            res.append([cur_start, a_end])
        return res

    result = []
    for start, end in base_merged:
        sub = subtract_one_base(start, end, cuts_merged)
        result.extend(sub)

    # Sort the resulting intervals by their start point
    result.sort(key=lambda x: x[0])

    # Merge adjacent or overlapping surviving intervals into minimal list
    final = []
    for interval in result:
        if not final:
            final.append(list(interval))
        else:
            last = final[-1]
            if interval[0] <= last[1]:
                if interval[1] > last[1]:
                    last[1] = interval[1]
            else:
                final.append(list(interval))
    return final
