def deep_copy(obj, _memo=None):
    if _memo is None:
        _memo = {}

    obj_id = id(obj)
    if obj_id in _memo:
        return _memo[obj_id]

    if obj is None or isinstance(obj, (bool, str, int, float)):
        _memo[obj_id] = obj
        return obj

    if isinstance(obj, list):
        copy_obj = []
        _memo[obj_id] = copy_obj
        for item in obj:
            copy_obj.append(deep_copy(item, _memo))
        return copy_obj

    if isinstance(obj, dict):
        copy_obj = {}
        _memo[obj_id] = copy_obj
        for key, value in obj.items():
            copy_obj[deep_copy(key, _memo)] = deep_copy(value, _memo)
        return copy_obj

    if isinstance(obj, set):
        copy_obj = set()
        _memo[obj_id] = copy_obj
        for item in obj:
            copy_obj.add(deep_copy(item, _memo))
        return copy_obj

    if isinstance(obj, tuple):
        copied_elements = [deep_copy(item, _memo) for item in obj]
        copy_obj = tuple(copied_elements)
        _memo[obj_id] = copy_obj
        return copy_obj

    _memo[obj_id] = obj
    return obj
