def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    negative = False
    if n < 0:
        negative = True
        n = -n
    base = len(alphabet)
    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base
    s = ''.join(reversed(digits))
    if negative:
        s = '-' + s
    return s


