        raise ValueError("empty string")
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
    if not s:
        raise ValueError("empty string after sign")
    base = len(alphabet)
    char_to_val = {ch: i for i, ch in enumerate(alphabet)}
    for ch in s:
        if ch not in char_to_val:
            raise ValueError(f"character {ch!r} not in alphabet")
    value = 0
    for ch in s:
        value = value * base + char_to_val[ch]
    if negative:
        value = -value
    return value
