import heapq

def topo_lex(graph):
    # Collect all nodes that appear either as a key or as a successor.
    nodes = set()
    for u in graph:
        nodes.add(u)
        for v in graph[u]:
            nodes.add(v)

    # Compute in-degree for each node.
    indegree = {node: 0 for node in nodes}
    for u in graph:
        for v in graph[u]:
            indegree[v] += 1

    # Initialize min-heap with all nodes that have in-degree 0.
    heap = []
    for node in nodes:
        if indegree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        # Decrement in-degree of all successors.
        for v in graph.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    # If not all nodes were visited, there is a cycle.
    if len(result) != len(nodes):
        return None
    return result
