function sqlTag(strings, ...values) {
  let text = '';
  const vals = [];
  let pIndex = 1;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      const v = values[i];

      if (v !== null && typeof v === 'object' && Array.isArray(v.values)) {
        // Nested sqlTag result: inline with renumbered placeholders
        const innerText = v.text != null ? v.text.replace(/\$(\d+)/g, (_, num) => '$' + (Number(num) + pIndex - 1)) : '';
        text += innerText;
        vals.push(...v.values);
        pIndex += v.values.length;
      } else if (Array.isArray(v)) {
        // Array: parenthesised comma-separated placeholders
        const ph = v.map((_, idx) => `$${pIndex + idx}`).join(',');
        text += `(${ph})`;
        vals.push(...v);
        pIndex += v.length;
      } else {
        // Primitive or other value
        text += `$${pIndex}`;
        vals.push(v);
        pIndex++;
      }
    }
  }

  return { text, values: vals };
}

