export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Array<(payload: any) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const list = this.handlers.get(k) || [];
    list.push(fn as any);
    this.handlers.set(k, list);
    return () => {
      const arr = this.handlers.get(k);
      if (arr) {
        this.handlers.set(k, arr.filter((h) => h !== fn));
      }
    };
  }

  emit<K extends keyof E>(k: K, ...payload: E[K] extends void ? [] : [E[K]]): void {
    const handlers = this.handlers.get(k);
    if (!handlers) return;
    if (payload.length === 0) {
      handlers.forEach((fn) => fn());
    } else {
      handlers.forEach((fn) => fn(payload[0]));
    }
  }
}

