export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }

export function ok<T, E>(value: T): Result<T, E> {
  return { ok: true, value }
}

export function err<T, E>(error: E): Result<T, E> {
  return { ok: false, error }
}

export function isOk<T, E>(x: Result<T, E>): x is { ok: true; value: T } {
  return x.ok === true
}

export function isErr<T, E>(x: Result<T, E>): x is { ok: false; error: E } {
  return x.ok === false
}

export function map<T, E, U>(r: Result<T, E>, f: (value: T) => U): Result<U, E> {
  if (isOk(r)) {
    return { ok: true, value: f(r.value) }
  }
  return { ok: false, error: r.error }
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  return isOk(r) ? r.value : defaultValue
}
